{"source":"import sys
import csv
import json
from decimal import Decimal, ROUND_HALF_UP, QUANTIZE


def normalize_category(raw):
    """Collapse whitespace, casefold; blank becomes 'uncategorized'."""
    collapsed = " ".join(raw.split())
    cf = collapsed.casefold()
    return "uncategorized" if cf == "" else cf


def fmt(value):
    """Quantize a Decimal to two places (ROUND_HALF_UP) and format with 2 decimals."""
    q = value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    if q == 0:
        q = Decimal("0.00")  # avoid "-0.00"
    return str(q)


def main():
    result = {"categories": [], "total": "0.00"}
    if len(sys.argv) < 2:
        print(json.dumps(result, ensure_ascii=False))
        return

    path = sys.argv[1]
    # Read as UTF-8; do not modify input bytes.
    with open(path, "r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        totals = {}
        for row in reader:
            status = (row.get("status") or "").strip().casefold()
            if status != "paid":
                continue
            category = normalize_category(row.get("category") or "")
            amount_raw = (row.get("amount") or "").strip()
            amount = Decimal(amount_raw) if amount_raw != "" else Decimal("0")
            rounded = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            totals[category] = totals.get(category, Decimal("0")) + rounded

    categories = [
        {"category": cat, "total": fmt(totals[cat])}
        for cat in sorted(totals.keys())
    ]
    grand = sum(totals.values(), Decimal("0"))
    result = {
        "categories": categories,
        "total": fmt(grand),
    }
    print(json.dumps(result, ensure_ascii=False))


if __name__ == "__main__":
    main()"}

